from attr import attrs, validators, disabled

@attrs
class C:
    x = attrs.field(validator=validators.instance_of(int))

def test_nested_disabled():
    try:
        with disabled():
            print("Outer disabled started")
            with disabled():
                print("Inner disabled started")
                C(x="not_int") # Should not raise
                print("Inner disabled finished")

            print("Inner disabled exited, still in outer disabled")
            C(x="not_int") # Should not raise
            print("Outer disabled finished")
    except TypeError as e:
        print(f"Caught unexpected TypeError: {e}")
        raise e
    else:
        print("Test passed!")

if __name__ == "__main__":
    test_nested_disabled()

