from attr import attrs, field
from attr import validators
from attr.validators import disabled
from attr._config import set_run_validators, get_run_validators

@attrs
class C:
    x = field(validator=validators.instance_of(int))

def test_pre_disabled():
    set_run_validators(False)
    print(f"Initial state: {get_run_validators()}") # Should be False
    try:
        with disabled():
            print("Inside disabled()")
            C(x="not_int") # Should not raise

        print("Outside disabled()")
        C(x="not_int") # Should still not raise because we started with False
    except TypeError as e:
        print(f"Caught unexpected TypeError: {e}")
        raise e
    else:
        print("Test passed!")

if __name__ == "__main__":
    test_pre_disabled()

